  "tower.staff.lede": "በአንድ ሰው አንድ መግቢያ፣ ስለዚህ ሁለት ሰዎች የሚያስፈልገው ውሳኔ በእውነት ሁለት ሰዎች ይወስዳል። ይህ ለአዲስ መግቢያም ይሠራል፦ አንድ የሠራተኛ አባል ይጠይቀዋል ሁለተኛው ያጸድቀዋል። አዲሱ ሰው የራሱን የይለፍ ቃል የሚመርጥበት ሊንክ በኢሜይል ይላክለታል፤ ከሠራተኞች ማንም አንድ በጭራሽ አይታየውም።",
  "tower.staff.ledeKey": "በማዋቀሪያ ቁልፍ ገብተዋል። ከሙከራ አካባቢ ውጭ፣ ማንም መግባት በማይችልበት ጊዜ ብቻ የሠራተኛ መለያ ብቻውን ይሠራል፣ መግባት የሚችለው እሱ ብቻ ለሆነ ሰው ብቻ ጥያቄን ያጸድቃል፣ እና ለሁሉም ሠራተኞች የአንድ ቀን ማሳወቂያ ሳይሰጥ ምንም መግቢያ አያስወግድም።",
  "tower.setup.title": "የኔትወርክ ሠራተኞችን ማዋቀር",
  "tower.setup.lede": "በማዋቀሪያ ቁልፍ ገብተዋል። በዚህ አገልጋይ ላይ የኔትወርክ ሠራተኞችን ያዋቅራል እና ሌላ ምንም አያደርግም፦ ሌላ ማያ አይከፍትም፣ ምንም አይወስንም ለማንም አይሠራም። የመጀመሪያውን መለያ እዚህ ይሥሩ፣ ከዚያ በእሱ ይግቡ።",
  "tower.staff.ask": "መለያውን ይጠይቁ",
  "tower.staff.asked": "ተጠይቋል። እስካሁን ምንም አልተፈጠረም። ሁለተኛ ሰው ሲያጸድቀው፣ ለ{name} የይለፍ ቃል የሚመርጥበት ሊንክ በኢሜይል ይላካል። ከሠራተኞች ማንም አንድ አይታየውም።",
  "tower.staff.askedKey": "ተጠይቋል። እስካሁን ምንም አልተፈጠረም። መግባት የሚችሉት እርስዎ ብቻ ነዎት፣ ስለዚህ በማዋቀሪያ ቁልፍ ራስዎ ያጸድቁታል፦ ይውጡ፣ በማዋቀሪያ ቁልፍ ይግቡ፣ እና በየኔትወርክ ሠራተኞች ስር ያጸድቁት። ከዚያ ለ{name} የይለፍ ቃል የሚመርጥበት ሊንክ በኢሜይል ይላካል። ከሠራተኞች ማንም አንድ አይታየውም።",
