  "tower.hazards.lede": "አሽከርካሪዎች በመንገዱ ላይ ያለውን ይናገራሉ፣ አደጋ ጠፍቷል የሚል አሽከርካሪ ግን አያስወግደውም። ማስወገድ ማስጠንቀቁን የሚያቆምበት ብቸኛው መንገድ ነው፣ ከዚህ ብቻ። ዝግ ነው የተባለ ድንበር ማንም ቢቃወምም ባይቃወምም እዚህ ይጠብቃል፣ ምክንያቱም ኔትወርኩ በዚያ ላይ የሚያደርገው የሠራተኞች ውሳኔ ነው።",
