  "tower.hazards.caveat": "— በሙሉ ክብደት፣ እና አሁንም ያንኑ ጭነቶች እየከለከለ። ተቃውሞ በራሱ ምንም አይለውጥም፣ ይህም ሆን ተብሎ ነው፦ በሌለ ድልድይ ላይ መሳሳት ማዞሪያ ያስከፍላል፣ አሁንም ባለ ድልድይ ላይ መሳሳት ሰው ይገድላል።",
