  "tower.papers.title": "ሰነዶች፦ ያለ ተሽከርካሪ ድርጅት ያሉ ተላላኪዎችና ተሽከርካሪዎች",
  "tower.papers.lede": "የተሽከርካሪ ድርጅት የራሱን ተሽከርካሪዎችና አሽከርካሪዎች እድሳት በFleet መተግበሪያ ይመዘግባል። ያለ ተሽከርካሪ ድርጅት የሚሠራ ተላላኪ እና የማንም የተሽከርካሪ ድርጅት ያልሆነ ተሽከርካሪ ያንን የሚያደርግ ቢሮ የላቸውም — የሚያልፍ ፈቃድ የሚነግራቸው ሳይኖር ከመንገድ ውጭ ያደርጋቸዋል። ያዩትን እዚህ ይመዝግቡ፤ አዲሱ ቀን የእድሳቱ ሙሉ ነገር ነው።",
