  "tower.anchors.lede": "እያንዳንዱ መውሰድ፣ ማድረስ፣ ማኅተም፣ ቅኝትና የጉዳት ሪፖርት በአንድ ሰንሰለት ውስጥ አሻራ ይደረግበታል። በቀን አንድ ጊዜ የቅርብ ጊዜ ቀለበቱ እኛ ወደማንቀይርበት የኦዲተር አድራሻ ይሄዳል። እስከዚያ ቀለበት ድረስ ያለ ማንኛውም ነገር በኋላ ከተቀየረ፣ ሰንሰለቱ ያንኑ ቀለበት አይሰጥም፣ የኦዲተሩም ቅጂ ያሳያል።",
