  "tower.pilot.howTitle": "እያንዳንዱ እንዴት እንደሚቆጠር",
  "tower.pilot.how.handshake": "ርክክብ፦ በካውንተር ርክክብ ወደ አውቶቡስ መሄድ ከሚገባቸው ጥቅሎች ውስጥ ሱቁ ወደ እሱ የቃኘው ድርሻ። አንድ የተተወ በምክንያት ሳይለይ ይቆጠርበታል። ግብ {target}፤ ከ{warn} በታች ከሆነ ስም ያስፈልገዋል።",
  "tower.pilot.how.loss": "የጠፋ ወይም የተጎዳ፦ በዚያ ሳምንት እንደጠፉ የተገለጹና እስከተቆለፈበት ጊዜ ያልተገኙ ጥቅሎች፣ እና በዚያ ሳምንት በጥቅሎች ላይ የተዘገቡ ችግሮች፣ በዚያ ሳምንት ለተቀበለው ለእያንዳንዱ ጥቅል። ግብ ከ{target} በታች፤ ከ{warn} በላይ ከሆነ ስም ያስፈልገዋል።",
  "tower.pilot.how.takeIn": "የመቀበል ጊዜ፦ የሱቆቹ መተግበሪያ ከለካቸው ጊዜያት መካከለኛው፣ ከመቀበሉ የመጀመሪያ ንክኪ ጀምሮ ጥቅሉ እስኪቀበል ድረስ። ከ15 ደቂቃ በላይ የረዘመ የተቋረጠ ነው እንጂ ቀርፋፋ አይደለም፣ አይቆጠርም። ግብ ከ{target} ሰከንድ በታች፤ ከ{warn} ሰከንድ በላይ ከሆነ ስም ያስፈልገዋል።",
  "tower.pilot.how.retention": "የሚሠሩ የመጀመሪያዎቹ ሱቆች፦ በሙከራ ፕሮጀክቱ የመጀመሪያ ሳምንት ካውንተር ከሠሩ ሱቆች ውስጥ በዚህ ሳምንት የሠሩት ድርሻ። ከሳምንት {week} ጀምሮ፣ ከ{target} ጋር ይመዘናል።",
  "tower.pilot.how.frozen": "ርክክቦችና የመቀበል ጊዜዎች የሚቆጠሩት መቀመጥ ከጀመሩበት ከ18 ኦክቶበር 2026 ጀምሮ ነው፤ ከዚያ በፊት ያሉ ሳምንታት ለእነሱ ምንም ቁጥር አያሳዩም።",
