  "tower.reports.lede": "የተዘገበ እያንዳንዱ ችግር፣ አዲሱ መጀመሪያ። ሠራተኞች እዚህ ምንም አይወስኑም፦ ሪፖርቱ የተሠራው ችግሩ በተዘገበበት ቅጽበት ከነበረው መዝገብ ነው፣ ለማንም የተሠራለት ደግሞ ለራሱ መድን ሰጪ ያስተላልፈዋል።",
