  "tower.amounts.h.freightBaseFee": "ለእያንዳንዱ ጭነት አንድ ጊዜ ይከፈላል። ትንሽ ተሽከርካሪ ከድርሻው ይጀምራል፦ ቫን ግማሽ፣ መኪና አንድ አምስተኛ፣ ሞተር ሳይክል ከመቶ ስምንት ክፍል።",
