  "tower.amounts.mathOver": "በካውንተር የተቀበለ ጥቅል {price} ያመጣል፣ በመጀመሪያ ክፍያው ላይ ባለ ማዕከል መለየት፣ መደርደሪያ ላይ ማስቀመጥና ማስረከብ ደግሞ {out} ይከፍላሉ፦ ከሚያመጣው በላይ። እያንዳንዱ ቁጥር በየትኛው ሳጥን ውስጥ እንዳለ ይፈትሹ።",
  "tower.amounts.negative": "{field} ከምንም ያነሰ ሊሆን አይችልም።",
  "tower.amounts.priceNeeded": "ጥቅል የሆነ ነገር ማስወጣት አለበት፦ ዋጋው ሱቅ አንዱን ለመቀበል የሚያስፈልገው ዋሌትም ነው።",
  "tower.amounts.nothingChanged": "እስካሁን ምንም አልተለወጠም።",
  "tower.amounts.saved": "ተቀምጧል። ከአሁን ጀምሮ የሚደረግ እያንዳንዱ እርምጃ እነዚህን ቁጥሮች ይጠቀማል።",
  "tower.topupfee.title": "ገንዘብ ማስገባት ምን ያስወጣል",
  "tower.topupfee.hint": "ከመነሻ መጠን በታች ባለ ሂሳብ መሙላት ላይ ቋሚ ክፍያ፣ በመነሻ መጠኑ ወይም ከዚያ በላይ ደግሞ ምንም። ቋሚ የሆነው የሚያስመልሰው በክፍያ እንጂ በብር ወጪ ስላልሆነ ነው — መቶኛ እኛ ለመሸከም ተመሳሳይ ለሚያስወጣን ሂሳብ መሙላት እጥፍ ያስከፍል ነበር። ከመነሻ መጠኑ በላይ ነጻ የሆነው በጠዋት ገንዘብ ላለቀበት ሱቅ ፈጽሞ እንቅፋት እንዳይሆን ነው። ሱቁ ሙሉውን መጠን ገቢ ይደረግለታል ለየብቻም ይቀነስበታል፣ ሁለቱም መስመሮች በመዝገቡ ላይ ይታያሉ።",
  "tower.topupfee.charge": "ከመነሻ መጠን በታች ክፍያ",
  "tower.topupfee.freeAbove": "በዚህ ወይም ከዚህ በላይ ነጻ",
