  "tower.topupfee.none": "ክፍያ የለም። በዚህ አገር ያሉ ሱቆችና መደብሮች በነጻ ሂሳብ ይሞላሉ፣ ሁለቱም መተግበሪያ ምንም ክፍያ አያሳዩም።",
  "tower.topupfee.current": "አሁን፦ ከ{freeAbove} በታች በማንኛውም ላይ {charge}። {freeAbove} ወይም ከዚያ በላይ ነጻ ነው።",
