  "tower.topupfee.fold.none": "ክፍያ የለም — ሂሳብ መሙላት ምንም አያስወጣም",
  "tower.topupfee.clearHint": "ምንም ላለማስከፈል ሁለቱንም ሳጥኖች ባዶ ያድርጉና ያስቀምጡ። ይህ ከዜሮ ክፍያ የተለየ ነው፣ እሱ ይከለከላል — ምንም የለም የሚል ክፍያ እንኳ በሱቅ ባለቤት ስክሪን ላይ ክፍያ ያስቀምጣል።",
  "tower.topupfee.needsBoth": "ሁለቱንም ያዘጋጁ፣ ወይም ሁለቱንም ባዶ ይተዉ። ከኋላው ክፍያ የሌለው መነሻ መጠን ማንንም አያስከፍልም፣ መነሻ መጠን የሌለው ክፍያ ደግሞ ብዙ ሂሳብ በመሙላት ማንም ሊያመልጠው የማይችል ነው።",
  "tower.topupfee.chargeTooLow": "ክፍያ ከምንም በላይ መሆን አለበት። ምንም ላለማስከፈል በምትኩ ሁለቱንም ሳጥኖች ባዶ ያድርጉ።",
  "tower.topupfee.thresholdTooLow": "መነሻ መጠኑ ከምንም በላይ መሆን አለበት፣ ያለዚያ ክፍያው በጭራሽ ሊወገድ አይችልም።",
  "tower.topupfee.tooSteep": "ይህ የመነሻ መጠኑ አንድ አምስተኛ ወይም ከዚያ በላይ ነው፣ ይህም የክፍያ ወጪ ሳይሆን በማነስ ላይ የተጣለ ታሪፍ ነው። ይህ መነሻ መጠን የሚፈቅደው ከፍተኛው {max} ነው።",
  "tower.topupfee.saved": "ተቀምጧል። በዚህ አገር ያለ እያንዳንዱ ሱቅና መደብር ከመክፈሉ በፊት ክፍያውን በሂሳብ መሙያ ሉሁ ላይ ያያል።",
