  "tower.companies.caveatLead": "እዚህ ምንም አይደመርም።",
  "tower.companies.caveat": "እነዚህ ኩባንያዎች በተለያዩ የገንዘብ ዓይነቶች ይከፈላሉ፣ በመካከላቸው ያለ ድምር ማንም በማያየው መንገድ የተሳሳተ ቁጥር ይሆናል። እያንዳንዱ ዓምድ በራሱ ገንዘብ ይቆያል።",
