  "tower.companies.groupCharges": "እናት ኩባንያው ምንም አያስከፍልም፦ የትም የመዝገብ ነጋዴ አይደለም፣ በደንበኛ ግብይትም ውስጥ ፈጽሞ አካል አይሆንም። የፈቃድ ክፍያውን ከእህት ኩባንያዎቹ ያገኛል።",
