  "tower.companies.noBooks": "የዚህን ኩባንያ የሂሳብ መዝገብ ማንበብ አልተቻለም። እንደ ዜሮ ሳይሆን እንደጎደለ ታይቷል — ዜሮ ቀሪ ሂሳብና ያልተመለሰ ጥያቄ አንድ ዓይነት ሆነው ይታያሉ፣ ተቃራኒ ትርጉም ግን አላቸው።",
