  "tower.companies.expiringWhatToDo": "እያንዳንዱን ካወጣው ጋር ያድሱ፣ ከዚያ የኩባንያውን መዝገብ ከፍተው በፈቃዶች ወይም በመድን ሥር “ከሰነዱ ጋር ይቀይሩ” የሚለውን ይጫኑ፦ አዲሱን ቀን ያስገቡና የታደሰውን ሰነድ ያያይዙ። ከዚያ ቅጽበት ጀምሮ ይቆጠራል። አስተዳዳሪዎቹ 60፣ 30፣ 14፣ 7 እና 1 ቀን ቀድመው፣ እንዲሁም ሰነድ ባበቃበት ቀን በኢሜይል ይነገራቸዋል።",
