  "tower.company.title": "የኩባንያ መዝገብ",
  "tower.company.ledeOwn": "የኩባንያዎ መዝገብ እርስዎ የሚይዙት ነው። የሕግ ዝርዝሮቹ፣ አድራሻዎቹ፣ ባለቤቶቹ፣ የታክስ ቁጥሮቹና አገሩ የሚጠይቀው፦ ይቀይሩና ያስቀምጡ። ፈቃድ፣ የመድን ፖሊሲ፣ የባንክ ሂሳብ ወይም ማን መፈረም እንደሚችል በአንድ ጊዜ አንድ፣ ከሚደግፈው ሰነድ ጋር ይለወጣል፣ ከዚያ ቅጽበትም ይቆጠራል። አብረውዎ ያሉ አስተዳዳሪዎችና ከእርስዎ በላይ ያለው ኩባንያ እያንዳንዱ እንዲህ ያለ ለውጥ በኢሜይል ይነገራቸዋል።",
  "tower.company.ledeDraft": "ኩባንያዎ ገና አልበራም። እስኪበራ ድረስ የSeeBuyGet ሠራተኞች መዝገቡን ያስገባሉ፣ ሁለተኛ ሰውም እያንዳንዱን ሰነድ ያረጋግጣል። ሰነዶችዎን በሰነዶች ሥር በመዝገብ ላይ ያስቀምጡ። ከበራ በኋላ መዝገቡ እርስዎ የሚይዙት ይሆናል።",
  "tower.company.ledeTheirs": "ይህ ኩባንያ በርቷል የራሱንም መዝገብ ይይዛል፦ አስተዳዳሪዎቹ ይቀይሩታል፣ እያንዳንዱን ፈቃድ፣ ፖሊሲ፣ የባንክ ሂሳብና ፈራሚ ከሚደግፈው ሰነድ ጋር። እርስዎ ያነቡታል።",
  "tower.company.lede": "ኩባንያን እውነተኛ የሚያደርግ ሁሉ — የሕግ ቅርጹ፣ ምዝገባው፣ መፈረም የሚችሉ ሰዎች፣ ባለቤቶቹ፣ የታክስ ቁጥሮቹ፣ ባንኩ፣ ፈቃዶቹ፣ መድኑና የሚደግፏቸው ሰነዶች። አገሩ ከመብራቱ በፊት ከኔትወርኩ በኩል እዚህ ይገባል።",
