  "tower.company.runningOut.own": "እያንዳንዱን ካወጣው ጋር ያድሱ፣ ከዚያ ከታች በፈቃዶች ወይም በመድን ሥር “ከሰነዱ ጋር ይቀይሩ” የሚለውን ይጫኑ፦ አዲሱን ቀን ያስገቡና የታደሰውን ሰነድ ያያይዙ። ከዚያ ቅጽበት ጀምሮ ይቆጠራል። አስተዳዳሪዎችዎ 60፣ 30፣ 14፣ 7 እና 1 ቀን ቀድመው፣ እንዲሁም ሰነድ ባበቃበት ቀን በኢሜይል ይነገራቸዋል።",
  "tower.company.runningOut.ownDraft": "እያንዳንዱን ካወጣው ጋር ያድሱ፣ ከዚያ የታደሰውን ሰነድ ከታች በሰነዶች ሥር በመዝገብ ላይ ያስቀምጡ። ኩባንያዎ እስኪበራ ድረስ የSeeBuyGet ሠራተኞች አዲሱን ቀን ያስገባሉ።",
  "tower.company.runningOut.staff": "ኩባንያው የራሱን ሰነዶች ያድሳል፦ ከአስተዳዳሪዎቹ አንዱ አዲሱን ቀን ከታደሰው ሰነድ ጋር ያያይዛል፣ ወዲያውም ይቆጠራል። 60፣ 30፣ 14፣ 7 እና 1 ቀን ቀድመው፣ እንዲሁም ሰነድ ባበቃበት ቀን በኢሜይል ይነገራቸዋል።",
  "tower.company.runningOut.staffDraft": "ገና አልበራም፤ ስለዚህ መዝገቡን ማስገባት የእርስዎ ነው፦ የታደሰው ሰነድ በሰነዶች ሥር በመዝገብ ላይ ተቀምጦ ከተረጋገጠ በኋላ፣ አዲሱን ቀኑን ከታች በፈቃዶች ወይም በመድን ሥር ያስገቡ።",
