  "tower.custodyCaps.hint": "አዲስ ሱቅ በአንድ ጊዜ ምን ያህል ጥቅሎችን እንደሚይዝ፣ በማንኛውም የተሽከርካሪ ድርጅት ውስጥ የሌለ አዲስ ተላላኪ ደግሞ ምን ያህል እንደሚሸከም። እያንዳንዱ ገደብ ለተላለፈ እያንዳንዱ ጥቅል በአንድ ይጨምራል፣ እርስዎ ካወጡት ቁጥር በኋላም ይነሳል። ገደብ ላለማድረግ ሁለቱንም ሳጥኖች ባዶ ያድርጉ። የተሽከርካሪ ድርጅት አሽከርካሪዎች እዚህ አይገደቡም፦ ድርጅታቸው ይመልስላቸዋል። ዝቅ አድርገው ይጀምሩ — ተላላኪ በ3፣ ከ50 በኋላ የሚነሳ — አገርዎ ማን እንደሚያደርስ እየተማረ ሲሄድም ያሳድጉት።",
