  "tower.carrierPapers.hint": "የተሽከርካሪ ድርጅት የትራንስፖርት ፈቃድና በጉዞ ላይ ላሉ ዕቃዎች የመድን ሽፋኑ እዚህ የሚመርጡት ምንም ቢሆን በሰነዶች ስክሪን ላይ ተመዝግበው ይታያሉ። ይህ የሚወስነው ማብቃት ምን እንደሚያደርግ ብቻ ነው፦ ከተተገበረ፣ የተሽከርካሪ ድርጅቱ ጉዞዎች ከሰሌዳው ይወርዳሉ፣ ሰነዱ እስኪታደስም ምንም አዲስ ሥራ ሊሸጥለት አይችልም፤ ካልተተገበረ፣ አንድ ሰው እርምጃ መውሰድ ያለበት ማስጠንቀቂያ ሆኖ ይቆያል። ቀድሞውኑ የተጀመሩ ጉዞዎች ሁልጊዜ ይጠናቀቃሉ። አብዛኛዎቹ የተሽከርካሪ ድርጅቶች እነዚህ ቀኖች ሳይኖሩ ተመዝግበዋል — ከመተግበርዎ በፊት ይመዝግቧቸው፣ ያለዚያ ምንም አይለወጥም።",
