  "tower.drivers.title": "የአሽከርካሪ ማመልከቻዎች",
  "tower.drivers.lede": "እኛን የሚጠብቁ የከባድ ተሽከርካሪ አሽከርካሪዎች — አዲስ ተላላኪዎች፣ እና በማንኛውም የተሽከርካሪ ድርጅት ውስጥ የሌሉ ለራሳቸው ለመሥራት የሚጠይቁ አሽከርካሪዎች። የሚመዘነው ይህ ሰው በሕጋዊ መንገድ መንዳት ይችል እንደሆነ ነው፤ ስለዚህ የላኩት ፈቃድ ከመንካት በኋላ ሳይሆን በረድፉ ላይ ይታያል።",
  "tower.drivers.asks": "በማንኛውም የተሽከርካሪ ድርጅት ውስጥ የለም፣ ለራሱ ለመሥራት ይጠይቃል፦ {vehicle} {plate}፣ የሚኖረው በ{country}። ማጽደቅ በእሱ ተላላኪ ያደርገዋል፤ የመዝገብ ማጣራቱን ምልክት ማድረግ የእርስዎ ድርሻ ነው።",
  "tower.drivers.askApproved": "ጸድቋል — አሁን ለራሱ በራሱ ተሽከርካሪ ይሠራል። በስልኩ ላይ ተነግሮታል።",
