  "tower.docs.lede": "ሁሉም ሰው ሲመዘገብ የሚስማማባቸው፦ የአጠቃቀም ውሎች፣ በመረጃው ላይ የሚሆነው፣ እና ኩኪዎች — አጠቃላይ ጽሑፎቹ፣ እና የአገር ሕግ የሚጨምረው። ለውጥ አዲስ ስሪት ነው፦ አንደኛችሁ ምን እንደተለወጠ በሚናገር ማስታወሻ ይጽፈዋል፣ ሌላኛው ደግሞ ያትመዋል። የሚመለከታቸው ሁሉ በመተግበሪያቸው ይነገራቸዋል። እያንዳንዱ ስሪት ይቀመጣል፣ ሊነበብና ሊነጻጸርም ይችላል።",
