  "tower.conn.adviser.off": "ምንም ቁልፍ አልተዘጋጀም፤ ስለዚህ አማካሪውን የሚጠይቅ የተሽከርካሪ ድርጅት ቢሮ አልተዘጋጀም ይባላል። እቅዶች ግን ሁሉም ይሠራሉ፦ አማካሪው እቅድን ያብራራል የተጠየቀውንም ይለውጣል፣ እቅዱ ራሱ ግን ፈጽሞ አያስፈልገውም ነበር።",
