  "tower.conn.adviser.answered": "በ{when} የጠየቀው የመጨረሻ ቢሮ መልስ አግኝቷል።",
  "tower.conn.adviser.refused": "በ{when} የጠየቀው የመጨረሻ ቢሮ አማካሪው አልተዘጋጀም ተብሎ ተነግሮታል፦ በዚህ ሰርቨር ላይ የተዘጋጀው ቁልፍ ተከልክሏል። ቁልፉን ይፈትሹ።",
