  "tower.conn.fact.smsCapValue": "በመጨረሻው ሰዓት ከ{perHour} {hour} · በመጨረሻው ቀን ከ{perDay} {day}",
  "tower.conn.sms.someFailed": "ይህ ሰርቨር ከተነሳ ወዲህ ከ{n} ውስጥ {failed} ሊሰጡ አልቻሉም።",
  "tower.conn.sms.where": "ኮድ በTwilio በኩል በጽሑፍ የሚላከው ሰርቨሩ ከሙከራ አካባቢ ውጪ ሲነሳ ከTWILIO_ACCOUNT_SID፣ ከምስክርነት (TWILIO_API_KEY_SID ከTWILIO_API_KEY_SECRET ጋር፣ ወይም TWILIO_AUTH_TOKEN) እና ጽሑፎች ከሚላኩበት (TWILIO_MESSAGING_SERVICE_SID፣ ወይም TWILIO_FROM) ጋር ነው። አንዳቸውም እዚህም ሆነ የትም አይታዩም። ኮድ በጽሑፍ የሚላከው ወደበራ አገር (የምንሠራባቸው ቦታዎች) ላለ ቁጥር ብቻ ነው፦ ከእሱ ጎን ምንም ዝርዝር የለም። Twilio በራሱ ኮንሶል ውስጥ በእጅ የሚለወጥ የራሱ ዝርዝር ይይዛል፣ በእኛ አይደለም፦ በSMS Geo Permissions ሥር ተመሳሳዮቹን አገሮች፣ ሌላ ምንም ሳይሆን፣ ያብሩ። ጽሑፍ አንድ ጊዜ ይላካል፦ ሊሰጥ ካልቻለ ሰውየው ይነገረዋል፣ እንደገናም ይጠይቃል። እስካሁን ምንም ጽሑፍ በእውነተኛው አቅራቢ አላለፈም፦ የመጀመሪያው እዚህ መታየት አለበት።",
