  "tower.ids.note.holderSilent": "ያዡ በሳምንቱ ውስጥ ምንም አልላከም። የጠያቂው ካርድ ቁጥሩን ከያዘ፣ መታወቂያው ወደ እሱ ሊሄድ ይችላል። የያዡ ምዝገባ ከዚያ ይያዛል እንጂ አይወገድም።",
  "tower.ids.note.claimantDiffers": "የጠያቂው የራሱ ካርድ የተለየ ቁጥር ይይዛል። ሲመዘገብ የሌላ ሰው ጽፏል፦ መታወቂያው ባለበት ይቆያል፣ እና በካርዱ ላይ ባለው ቁጥር ይመዘገባል።",
  "tower.ids.note.holderDiffers": "የያዡ የራሱ ካርድ የተለየ ቁጥር ይይዛል፦ የእሱ በስህተት ተጽፏል። መታወቂያው ወደ ጠያቂው ከሄደ፣ የያዡ መዝገብ ያነበቡትን ቁጥር ይወስዳል እና ማንም አይያዝም።",
  "tower.ids.note.bothMatch": "ሁለቱም ካርዶች ይህን ቁጥር ይይዛሉ፣ ስለዚህ አንዱ እውነተኛ አይደለም፣ ፎቶም ሁልጊዜ የትኛው እንደሆነ ሊናገር አይችልም። እያንዳንዱን ፊት ከካርዱ፣ በእያንዳንዱ የመጀመሪያ ሥዕል ውስጥ ካለው ማጣቀሻ፣ እና ያዡ ሲመዘገብ ከላከው ጋር ያወዳድሩ። መለየት ካልቻሉ፣ ከያዡ ጋር ይተዉት እና ይናገሩ፦ ያላገኘው ከካርዱ እራሱ ጋር ሊመጣ ይችላል።",
  "tower.ids.note.nothingOnRecord": "ያዡ ሲመዘገብ የመታወቂያ ቅጂ አልላከም፣ ስለዚህ ፎቶዎቹን የሚያወዳድሩበት ቀደም ያለ ምንም የለም።",
  "tower.ids.sentBack": "በ{why} ተመልሷል",
  "tower.ids.wait.opened": "የጠያቂውን ፎቶዎች በመጠበቅ ላይ። ያዡ ገና አልተነገረውም።",
  "tower.ids.wait.answering": "ያዡ ተነግሮታል እና ለመመለስ አንድ ሳምንት አለው። እሱ ሲመልስ፣ ወይም ሳምንቱ ሲያልቅ ሊወሰን ይችላል።",
