  "tower.ids.over": "እዚህ የሚወሰን ምንም አልቀረም።",
  "tower.ids.proposeLede": "መጀመሪያ በእያንዳንዱ ካርድ ላይ ያለውን ቁጥር ያንብቡ። ከዚያ የማን መታወቂያ እንደሆነ ይናገሩ። ሁለተኛ ሠራተኛ እስኪያጸድቀው ድረስ ምንም አይለወጥም።",
  "tower.ids.recordLede": "የቀጠሮው ቀን መጥቷል። ማን እንደመጣ ይናገሩ፣ ያሳዩዎትን እያንዳንዱ ካርድ ላይ ያለውን ቁጥር ያንብቡ፣ እና የማን መታወቂያ እንደሆነ ይናገሩ። ሁለተኛ ሠራተኛ ያጸድቀዋል፣ ያ የመጨረሻ ነው።",
